function renderInputGroupTextarea(
  props: Partial<Record<keyof ComponentProps<typeof InputGroupTextarea>, unknown>> = {},
) {
  cleanup()
  render(
    <InputGroup>
      <InputGroupTextarea
        data-subject
        {...({
          id: 'feedback-textarea',
          placeholder: 'Share your thoughts...',
          ...props,
        } as ComponentProps<typeof InputGroupTextarea>)}
      />
    </InputGroup>,
  )
  return document.querySelector('[data-subject]')?.closest('[data-slot="input-group-control"]')
}

function classesOfInputGroupTextarea(
  props: Partial<Record<keyof ComponentProps<typeof InputGroupTextarea>, unknown>> = {},
) {
  return renderInputGroupTextarea(props)?.getAttribute('class')?.split(' ') ?? []
}

